EXPORT int TreeFindNode(char const *path, int *outnid)
{
  return _TreeFindNode(*TreeCtx(), path, outnid);
}

EXPORT int TreeFindNodeWild(char const *path, int *nid_out, void **ctx_inout, int usage_mask)
{
   return _TreeFindNodeWild(*TreeCtx(), path, nid_out, ctx_inout, usage_mask);
}

EXPORT int TreeFindNodeEnd(void **ctx_in)
{
  return _TreeFindNodeEnd(*TreeCtx(), ctx_in);
}
EXPORT char *TreeAbsPath(char const *inpath)
{
  return _TreeAbsPath(*TreeCtx(), inpath);
}
EXPORT int _TreeFindNodeWild(void *dbid, char const *path, int *nid_out, void **ctx_inout, int usage_mask)
{
  int status = TreeNORMAL;
  PINO_DATABASE *dblist = (PINO_DATABASE *) dbid;
  int wild = 0;
  SEARCH_CTX *ctx;
  int not_first_time = 1;

  if (!IS_OPEN(dblist))
    return TreeNOT_OPEN;
  if (dblist->remote)
    return FindNodeWildRemote(dbid, path, nid_out, ctx_inout, usage_mask);
  if (*ctx_inout == NULL) {
    not_first_time = 0;
    ctx = (SEARCH_CTX *)calloc(1, sizeof(SEARCH_CTX));
    status = WildParse(path, ctx, &wild);
    if STATUS_NOT_OK
      return(status);
    *ctx_inout = ctx;
    NODELIST *tail=NULL;
    ctx->default_node = dblist->default_node;
    ctx->answers = Search(dblist, ctx, ctx->terms, dblist->default_node, &tail);
    ctx->answers = Filter(ctx->answers, usage_mask); 
    if (ctx->answers && (ctx->answers->node == ctx->default_node) && wild) {
      NODELIST *tmp = ctx->answers;
      ctx->answers = ctx->answers->next;
      free(tmp);
    }
 }
  else {
    ctx = *ctx_inout;
  }
  if (ctx->answers) {
    NODELIST *tmp;
    tmp = ctx->answers->next;
    *nid_out = node_to_nid(dblist, ctx->answers->node, (NID *)nid_out);
    free(ctx->answers);
    ctx->answers = tmp;    
  }
  else {
    status = (not_first_time) ? TreeNMN : TreeNNF;
  }
  return status;
}

EXPORT int _TreeFindNode(void *dbid, char const *path, int *outnid)
{
  int status = TreeNORMAL;
  PINO_DATABASE *dblist = (PINO_DATABASE *) dbid;
  int wild = 0;
  SEARCH_CTX ctx = {0};
  NODELIST *answer = NULL;
  NODELIST *tail = NULL;

  if (!IS_OPEN(dblist))
    return TreeNOT_OPEN;
  if (dblist->remote)
    return FindNodeRemote(dblist, path, outnid);

  status = WildParse(path, &ctx, &wild);
  if STATUS_NOT_OK
    goto done;
  if (wild) {
    status = TreeNOWILD;
    goto done;
  }
  ctx.default_node = dblist->default_node;
//  ctx.terms->start_node = ctx.default_node;
  answer = Search(dblist, &ctx, ctx.terms, dblist->default_node, &tail);
  if (answer) {
    *outnid = node_to_nid(dblist, answer->node, (NID *)outnid);
    FreeNodeList(answer);
  }
  else {
    status = TreeNNF;
  }
 done:
  FreeSearchCtx(&ctx);
  return (status & 1) ? TreeNORMAL : status;
}
EXPORT int _TreeFindNodeEnd(void *dbid __attribute__ ((unused)), void **ctx)
{
  if (ctx) {
    if (*ctx) {
      FreeSearchCtx(*ctx);
      free(*ctx);
      *ctx = NULL;
    }
  }
  return TreeNORMAL;
}

STATIC_ROUTINE void FreeSearchCtx(SEARCH_CTX *ctx)
{
  free(ctx->wildcard);
  FreeSearchTerms(ctx->terms);
}
STATIC_ROUTINE NODELIST *Search(PINO_DATABASE *dblist, SEARCH_CTX *ctx, SEARCH_TERM *term, NODE *start, NODELIST **tail)
{
  NODELIST *nodes = Find(dblist, term, start, tail);
  if (nodes) {
    NODELIST *more_nodes = NULL;
    NODELIST *more_tail = NULL;    
    if(term->next) {
      NODELIST *these_nodes = NULL;
      NODELIST *these_tail = NULL;
      NODELIST *n;
      for (n=nodes; n; n=n->next) {
        these_nodes = Search(dblist, ctx, term->next, n->node, &these_tail);
        if (these_nodes) {
          more_nodes = ConcatenateNodeLists(more_nodes, &more_tail, these_nodes, these_tail);
        }
      }
      FreeNodeList(nodes);
      *tail = more_tail;
      return(more_nodes);
    }
    else{
      return nodes;
    }
  }
  else{
    return NULL;
  } 
}

STATIC_ROUTINE inline int Wild(char *term) 
{
  return (strchr(term, '*') || strchr(term, '?') || strchr(term, '%'));
}

STATIC_ROUTINE NODELIST *Find(PINO_DATABASE *dblist, SEARCH_TERM *term, NODE *start, NODELIST **tail)
{
  NODELIST *answer = NULL;
  if (((term->search_type==CHILD) || (term->search_type==MEMBER)) && (! Wild(term->term))) {
    term->search_type = CHILD_OR_MEMBER;
  }
  switch (term->search_type) {
    case (CHILD) : {
      NODE *n=child_of(dblist, start);
      for (; n; n = brother_of(dblist, n)) {
        char *trimmed = Trim(n->name,sizeof(NODE_NAME));
        if (match(term->term, trimmed)) {
          answer = AddNodeList(answer, tail, n);
        }
        free(trimmed);
      }
      break;
    }
    case (MEMBER) : {
      NODE *n;
      for (n=member_of(start); n; n = brother_of(dblist, n)) {
        char *trimmed = Trim(n->name, sizeof(NODE_NAME));
        if (match(term->term, trimmed)) {
          answer = AddNodeList(answer, tail, n);
        }
        free(trimmed);
      }
      break;
    }
    case (CHILD_OR_MEMBER) : {
      NODE *n;
      for (n=member_of(start); n; n = brother_of(dblist, n)) {
        char *trimmed = Trim(n->name, sizeof(NODE_NAME));
        if (match(term->term, trimmed)) {
          answer = AddNodeList(answer, tail, n);
        }
        free(trimmed);
      }
      n=child_of(dblist, start);
      for (; n; n = brother_of(dblist, n)) {
        char *trimmed = Trim(n->name, sizeof(NODE_NAME));
        if (match(term->term, trimmed)) {
          answer = AddNodeList(answer, tail, n);
        }
        free(trimmed);
      }
      break;
    }
    case (CHILD_SEARCH) : {
      answer = FindChildren(dblist, term, start, tail);
      break;
    }
    case (MEMBER_SEARCH) : {
      answer = FindMembers(dblist, term, start, tail);
      break;
    }
    case (CHILD_OR_MEMBER_SEARCH) : {
      answer = FindMembersOrChildren(dblist, term, start, tail);
      break;
    }
    case (TAG):
    case (TAG_TREE): {
      answer = FindTagWild(dblist, term, tail);
      break;
    }
    case (PARENT) :
    {
      answer = AddNodeList(answer, tail, parent_of(dblist, start));
      break;
    }
    case (ANCESTOR): {
      NODE *parent = parent_of(dblist, start);
      if (parent) {
        char *trimmed = Trim(parent->name, sizeof(NODE_NAME));
        char *search_term = (strlen(term->term)) ? term->term : "*";
        if (match(search_term, trimmed))
          answer = AddNodeList(answer, tail, parent);
        free(trimmed);
      }
      break;
    }
    case (ANCESTOR_SEARCH): {
      NODE *parent = parent_of(dblist, start);
      while (parent) {
        char *trimmed = Trim(parent->name, sizeof(NODE_NAME));
        char *search_term = (strlen(term->term)) ? term->term : "*";
        if (match(search_term, trimmed))
          answer = AddNodeList(answer, tail, parent);
        free(trimmed);
        parent = parent_of(dblist, parent);
      }
      break;
    }

    default: {
      printf("Search for type %d not implimented\n", term->search_type);
      return NULL;
      break;
    }
  }
  return(answer);
}

STATIC_ROUTINE NODELIST *FindTags(PINO_DATABASE *dblist, TREE_INFO *info, int treenum, char *tagname, NODELIST **tail)
{
  NODELIST *answer = NULL;
  TAG_INFO *tptr = info->tag_info;
  int i;
  NID nid;
  int tag_wild = IsWild(tagname);
  *tail = NULL;

  nid.tree = treenum;
  if(match(tagname, "TOP")) {
    nid.node = 0;
    NODE *n = nid_to_node(dblist, &nid);
    if (n->usage == TreeUSAGE_SUBTREE_REF) {
      n = child_of(dblist, n);
    }
    answer = AddNodeList(answer, tail, n);
  }
  else { 
    for (i=0; i<info->header->tags; i++) {
      char *trimmed = Trim(tptr[i].name, sizeof(TAG_NAME));
      if(match(tagname, trimmed)) {
        NODE *n;
        nid.node = tptr[i].node_idx;
        n = nid_to_node(dblist, &nid);
        if (n->usage == TreeUSAGE_SUBTREE_REF) {
          n = child_of(dblist, n);
        }
        answer = AddNodeList(answer, tail, n);
        if (! tag_wild) {
          free(trimmed);
          break;
        }
      }
      free(trimmed);
    }
  }
  return(answer);
}

STATIC_ROUTINE inline int IsWild(char *str)
{
  return (strchr(str, '*') || strchr(str, '%'));
