STATIC_ROUTINE TREE_INFO *GetDefaultTreeInfo(PINO_DATABASE *dblist, int *treenum)
{
  TREE_INFO *info;
  int  i = 0;
  NID nid;
  node_to_nid(dblist, dblist->default_node, &nid);
  *treenum = nid.tree; 
  for (info=dblist->tree_info; i < *treenum; info = info->next_info, i++);
