int			TdiLexQuote(
int			len,
unsigned char		*str,
struct marker		*mark_ptr)
{
char		c, c1, *cptr = TdiRefZone.a_cur;
int		cur = 0, limit;

	while ((c = input()) && c != str[0]) if (c == '\\') input();
